code='''def transform(grid):
    out=[row[:] for row in grid]
    candidates={}
    for color in set(v for row in grid for v in row):
        if color in (0,1): continue
        pts={(r,c) for r,row in enumerate(grid) for c,v in enumerate(row) if v==color}
        comps=[]
        while pts:
            stack=[pts.pop()]; comp=[]
            while stack:
                r,c=stack.pop(); comp.append((r,c))
                for q in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                    if q in pts: pts.remove(q); stack.append(q)
            comps.append(comp)
        comps=[comp for comp in comps if len(comp)==3]
        if len(comps)==2: candidates[color]=comps
    if not candidates: return out
    # The non-blue repeated pair is the construction; blue pairs are decoys.
    color,comps=next(iter(candidates.items()))
    ps=comps[0]+comps[1]
    rs=[p[0] for p in ps]; cs=[p[1] for p in ps]
    r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
    centers=[(sum(p[0] for p in comp)/3,sum(p[1] for p in comp)/3) for comp in comps]
    filled=(centers[0][0]-centers[1][0])*(centers[0][1]-centers[1][1])<0
    for r in range(r0,r1+1):
        for c in range(c0,c1+1):
            if out[r][c]==color: continue
            if filled or r in set(rs) or c in (c0,c1):
                out[r][c]=3 if filled and r not in set(rs) and c not in (c0,c1) else color+1
    return out
'''
